#!/usr/bin/env bash
# Writes secrets.properties and app/google-services.json from the secrets of the
# GitHub Environment a job runs in. Shared by pr-check.yml and build-apk.yml.
#
# CI only. On a developer machine use scripts/use-env.sh, which writes the same
# files from secrets/<environment>/.
#
# Reads from the environment of the step:
#   TARGET_ENVIRONMENT    GitHub Environment of the job (develop, staging, production)
#   APP_ENVIRONMENT       value written as ENVIRONMENT (dev, staging, prod)
#   SECRETS_PROPERTIES    content of secrets/<environment>/secrets.properties
#   GOOGLE_SERVICES_JSON  content of secrets/<environment>/google-services.json

set -euo pipefail

cd "$(dirname "$0")/../.."

fail() {
  echo "$*" >&2
  exit 1
}

for name in SECRETS_PROPERTIES GOOGLE_SERVICES_JSON; do
  [ -n "${!name:-}" ] || fail "${name} is not set for the ${TARGET_ENVIRONMENT} environment."
done

# ENVIRONMENT is written here from the GitHub Environment of the job, never read
# from the secret. Only the key name is checked and reported, never a value.
if grep -Eq '^[[:space:]]*ENVIRONMENT([[:space:]=:]|$)' <<< "${SECRETS_PROPERTIES}"; then
  fail "Remove the ENVIRONMENT line from the SECRETS_PROPERTIES secret of the ${TARGET_ENVIRONMENT} environment: the workflow sets it."
fi

{
  echo "# Generated by CI from the SECRETS_PROPERTIES secret of the ${TARGET_ENVIRONMENT} environment."
  echo "ENVIRONMENT=${APP_ENVIRONMENT}"
  printf '%s\n' "${SECRETS_PROPERTIES}"
} > secrets.properties
printf '%s\n' "${GOOGLE_SERVICES_JSON}" > app/google-services.json
